import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const r="/assets/mot_1.DCbIcIKc.PNG",s="/assets/mot_2.C4yFiXSI.PNG",n="/assets/Mot_4.2girgy_O.PNG",l="/assets/mot_3.DiKOuwGi.PNG",b=JSON.parse('{"title":"Motilal Oswal","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/motilal-oswal.md","filePath":"connect-brokers/brokers/motilal-oswal.md"}'),c={name:"connect-brokers/brokers/motilal-oswal.md"};function d(p,e,g,u,h,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="motilal-oswal" tabindex="-1">Motilal Oswal <a class="header-anchor" href="#motilal-oswal" aria-label="Permalink to &quot;Motilal Oswal&quot;">​</a></h1><p>Motilal Oswal Financial Services Limited (MOFSL) is one of India&#39;s leading financial services companies, offering a comprehensive suite of investment and trading services. Their API platform provides developers and algo traders with programmatic access to trading capabilities including order placement, portfolio management, and market data.</p><p>Tradeboard seamlessly integrates with Motilal Oswal&#39;s API, enabling you to execute automated trading strategies across equity, derivatives, currency, and commodity segments.</p><h3 id="getting-api-credentials" tabindex="-1"><strong>Getting API Credentials</strong> <a class="header-anchor" href="#getting-api-credentials" aria-label="Permalink to &quot;**Getting API Credentials**&quot;">​</a></h3><h4 id="step-1-access-the-api-portal" tabindex="-1"><strong>Step 1: Access the API Portal</strong> <a class="header-anchor" href="#step-1-access-the-api-portal" aria-label="Permalink to &quot;**Step 1: Access the API Portal**&quot;">​</a></h4><p>Visit the Motilal Oswal OpenAPI registration portal:</p><p><a href="https://invest.motilaloswal.com/moAPI/" target="_blank" rel="noreferrer">https://invest.motilaloswal.com/moAPI/</a></p><h4 id="step-2-register-your-application" tabindex="-1"><strong>Step 2: Register Your Application</strong> <a class="header-anchor" href="#step-2-register-your-application" aria-label="Permalink to &quot;**Step 2: Register Your Application**&quot;">​</a></h4><ol><li>Log in with your Motilal Oswal trading credentials</li></ol><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><ol start="2"><li>Navigate to <strong>My APIs</strong></li></ol><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><ol start="3"><li>Set Up TOTP - Copy the 32-character secret key and Add this key to your preferred authenticator app</li><li>Click on <strong>Create on API Key</strong></li></ol><figure><img src="'+l+`" alt=""><figcaption></figcaption></figure><ol start="5"><li>Fill in the required details:</li></ol><ul><li><strong>App Name:</strong> Your application name (e.g., &quot;Tradeboard Trading&quot;)</li><li><strong>Redirect URL:</strong> <code>http://127.0.0.1:5000/motilal/callback</code></li></ul><ol start="6"><li>Submit the registration</li></ol><h4 id="step-3-obtain-your-api-key" tabindex="-1"><strong>Step 3: Obtain Your API Key</strong> <a class="header-anchor" href="#step-3-obtain-your-api-key" aria-label="Permalink to &quot;**Step 3: Obtain Your API Key**&quot;">​</a></h4><ul><li>Your trading account number or Client Code will be your API Key.</li><li>Copy the API Key generated and use as your API Secret</li></ul><h4 id="configuration" tabindex="-1"><strong>Configuration</strong> <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;**Configuration**&quot;">​</a></h4><p> Set up your environment variables in a <code>.env</code> file for motilal&#39;s :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Motilal Oswal API Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;your_client_code&#39; #Use your client code as api key</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_api_key_here&#39;  #Use your generated API Key as API secret in .env file</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/motilal/callback&#39;</span></span></code></pre></div><h3 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h3><p>Clicking Connect opens the Motilal Oswal login form. It asks for four values:</p><ul><li><strong>User ID</strong>, your client code</li><li><strong>Password</strong>, your trading password (Tradeboard hashes it with the API key before sending it)</li><li><strong>TOTP</strong>, the 6-digit code from the authenticator app you set up in Step 2</li><li><strong>Date of Birth</strong>, the 2FA date in <code>DD/MM/YYYY</code> format</li></ul><p>Integrating with <strong>Motilal APIs</strong> unlocks the ability to automate strategies, execute trades, and analyze data directly within your own infrastructure. When used with <strong>Tradeboard</strong>, you can self-host and run your entire algo trading stack, with full control and zero vendor lock-in.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/motilal/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,30)])])}const y=t(c,[["render",d]]);export{b as __pageData,y as default};
